mapper.select:
SELECT COUNT(*) AS pomodoro_count,
       COALESCE(SUM(duration_minutes), 0) AS focus_minutes
FROM pomodoro_session
WHERE user_id = #{userId}
  AND completed_at >= #{start}
  AND completed_at < #{end}

SELECT COUNT(*)
FROM task
WHERE user_id = #{userId}
  AND completed = TRUE
  AND completed_at >= #{start}
  AND completed_at < #{end}

SELECT DATE(completed_at) AS stat_date,
       COUNT(*) AS pomodoro_count
FROM pomodoro_session
WHERE user_id = #{userId}
  AND completed_at >= #{start}
  AND completed_at < #{end}
GROUP BY DATE(completed_at)
ORDER BY DATE(completed_at)
